// CRISPY_REPORT_BASIC_SIGNATURE:be691bf7
// Generated by Crispy Report Basic Mode
// CRISPY_REPORT_BASIC_GENERATOR:4
// Edit in Advanced mode for full control.
#import "@local/crispy-charts:0.1.1": crispy-chart
#set text(font: ("Inter", "Noto Naskh Arabic", "Noto Sans Arabic", "Inter"), size: 9pt, lang: "en", dir: ltr)

#align(center)[
  #text(font: "Inter", size: 16pt, weight: "bold", fill: rgb("1e293b"))[#data.title]
  #v(0.3em)
  #text(size: 9pt, fill: rgb("64748b"))[#data.subtitle]
]

#v(1em)

#if "filters_map" in data [
  #align(center)[#text(size: 11pt, weight: "semibold")[#if "party" in data.filters_map { data.filters_map.party } else if "account" in data.filters_map { data.filters_map.account }]]
  #align(center)[#text(size: 8pt)[#if "from_date" in data.filters_map { data.filters_map.from_date } #h(0.5em)–#h(0.5em) #if "to_date" in data.filters_map { data.filters_map.to_date }]]
]
#if "filters" in data and data.filters.len() > 0 [
  #block(
    fill: rgb("f5f5f5"),
    inset: 10pt,
    radius: 4pt,
    width: 100%,
  )[
    #text(size: 9pt, weight: "semibold")[Filters:]
    #v(0.5em)
    #grid(
      columns: (auto, 1fr) * 2,
      column-gutter: 12pt,
      row-gutter: 6pt,
      ..data
        .filters
        .map(f => (
          text(size: 8pt, weight: "medium")[#f.label:],
          text(size: 8pt)[#f.value],
        ))
        .flatten()
    )
  ]
  #v(1em)
]

// CRISPY-CHART-SECTION v2
#if "chart_spec" in data and data.chart_spec.engine == "lilaq" [
    #align(center)[
      #crispy-chart(data.chart_spec, theme: data.chart_theme, width: 100%, height: 220pt)
    ]
  #v(12pt)
]
#if "chart_spec" in data and data.chart_spec.engine == "frappe_svg" and "chart_svg" in data and data.chart_svg != "" [
  #align(center)[
    #image(data.chart_svg, width: 100%, height: 220pt, fit: "contain")
  ]
  #v(12pt)
]
// /CRISPY-CHART-SECTION

#if "report_summary" in data and data.report_summary.len() > 0 [
  #block(
    inset: (x: 8pt, y: 6pt),
    width: 100%,
  )[
    #grid(
      columns: (1fr, auto),
      column-gutter: 12pt,
      row-gutter: 4pt,
      ..data
        .report_summary
        .map(item => (
          text(size: 8pt, weight: "medium")[#item.label],
          text(size: 8pt, fill: if "color_class" in item and item.color_class == "green" { rgb("#22C55E") } else if "color_class" in item and item.color_class == "red" { rgb("#EF4444") } else if "color_class" in item and item.color_class == "blue" { rgb("#3B82F6") } else { rgb("#0f172a") })[
            #if "formatted_value" in item and item.formatted_value != "" { item.formatted_value } else { item.value }
          ],
        ))
        .flatten()
    )
  ]
  #v(0.8em)
]

#let cp_column_width(col) = {
  if "width_kind" in col {
    if col.width_kind == "auto" { auto }
    else if col.width_kind == "fr" { col.width_value * 1fr }
    else if col.width_kind == "pt" { col.width_value * 1pt }
    else if col.width_kind == "em" { col.width_value * 1em }
    else if col.width_kind == "rem" { col.width_value * 1em }
    else if col.width_kind == "%" { col.width_value * 1% }
    else if col.width_kind == "cm" { col.width_value * 1cm }
    else if col.width_kind == "mm" { col.width_value * 1mm }
    else if col.width_kind == "in" { col.width_value * 1in }
    else { auto }
  } else { auto }
}

#let cp-columns = data.columns
#let cp-row-cells(row) = row.cells

#table(
  columns: cp-columns.map(cp_column_width),

  stroke: (x, y) => (
    top: if y == 0 { 1pt } else { 0.5pt },
    bottom: 0.5pt,
    left: 0pt,
    right: 0pt,
  ),

  align: (x, y) => {
    if y == 0 {
      center + horizon
    } else if cp-columns.at(x).is_numeric {
      right + horizon
    } else {
      left + horizon
    }
  },

  fill: (x, y) => {
    if y == 0 { rgb("B3D7FF") }
  },

  inset: (top: 6pt, right: 8pt, bottom: 6pt, left: 8pt),

  table.header(
    repeat: true,
    ..cp-columns.map(col => text(..(
  font: "Inter",
  size: 9pt,
  style: "normal",
  weight: 700,
  fill: rgb("0f172a")
))[#col.label])
  ),

  ..data
    .rows
    .enumerate()
    .map(row_entry => {
      let row-index = row_entry.at(0)
      let row = row_entry.at(1)
      let next-row = if row-index + 1 < data.rows.len() { data.rows.at(row-index + 1) } else { none }
      let keep-with-next = row.role == "section" or (next-row != none and (next-row.role == "calculation" or next-row.role == "grand_total"))
      let row-breakable = row.role == "detail" or row.role == "auxiliary" or row.role == "spacer"
      let row-fill = if row.role == "section" { rgb("eff6ff") } else if row.role == "calculation" { rgb("f8fafc") } else if row.role == "grand_total" { rgb("e2e8f0") } else { none }
      if row.role == "section" {
        let heading = row.cells.at(0)
        (table.cell(colspan: data.columns.len(), fill: row-fill, breakable: false)[#block(sticky: true)[#text(..(
  font: "Inter",
  size: 9pt,
  style: "normal",
  weight: 700,
  fill: rgb("0f172a")
))[#heading.value]]],)
      } else {
      cp-row-cells(row).enumerate().map(cell_entry => {
        let idx = cell_entry.at(0)
        let cell = cell_entry.at(1)
        let cell-dir = if cell.is_numeric or ("is_ltr" in cell and cell.is_ltr) { ltr } else { ltr }
        let content = if row.is_bold {
          text(dir: cell-dir, ..(
  font: "Inter",
  size: 9pt,
  style: "normal",
  weight: 700,
  fill: rgb("0f172a")
))[#cell.value]
        } else {
          text(dir: cell-dir, ..(
  font: "Inter",
  size: 9pt,
  style: "normal",
  weight: 400,
  fill: rgb("0f172a")
))[#cell.value]
        }
        if idx == 0 and "indent" in row and row.indent != none and row.indent > 0 {
          table.cell(fill: row-fill, breakable: row-breakable)[#block(sticky: keep-with-next)[#box(inset: (left: row.indent * 10pt))[#content]]]
        } else {
          table.cell(fill: row-fill, breakable: row-breakable)[#block(sticky: keep-with-next)[#content]]
        }
      })
      }
    })
    .flatten()
)

#v(1em)
#align(right)[
  #text(size: 8pt, fill: rgb("64748b"))[
    Total Records: #data.total_rows
  ]
]
